// SLIDE DE FECHAMENTO -- FONTE UNICA DE VERDADE
// O ultimo slide do carrossel e sempre este, e nao e escrito pela IA. Dois
// motivos: a chamada da pagina nao deve variar de semana para semana, e o
// aviso de onde esta o prompt precisa ser sempre verdadeiro. Enquanto essa
// frase era gerada pelo modelo, ela apontava para lugares que nao existiam.
// Se quiser mudar a chamada, mude AQUI e vale para todo Mao na Massa.

const PERFIL = '@iaclube';
const SITE = 'iaclube.help';

const d = $input.first().json;

const slideCta = {
  papel: 'cta',
  titulo: 'O prompt tá na legenda',
  texto: `Copia, cola e testa hoje. Tem tutorial novo toda semana no ${PERFIL}, e mais conteúdo em ${SITE}.`
};

return [{
  json: {
    ...d,
    slides: [...(d.slides || []), slideCta]
  }
}];

// Traz as tarefas do dia a dia que ja viraram post, para nao repetir o mesmo
// caso de uso. Guarda tambem as ferramentas ja citadas: elas PODEM se repetir
// (a mesma ferramenta resolve varias tarefas), mas e bom o modelo saber quais
// ja apareceram muito, para variar o repertorio.
const linhas = $input.all().map(item => item.json);

const tarefasUsadas = linhas
  .map(l => l.tarefa)
  .filter(t => t);

const tarefasNormalizadas = linhas
  .map(l => l.tarefa_normalizada || l.tarefa)
  .filter(t => t);

// ferramentas_citadas e gravado como texto separado por virgula;
// aqui juntamos tudo e contamos quantas vezes cada uma apareceu.
const contagem = {};
linhas.forEach(l => {
  String(l.ferramentas_citadas || '')
    .split(',')
    .map(f => f.trim())
    .filter(f => f)
    .forEach(f => { contagem[f] = (contagem[f] || 0) + 1; });
});

const ferramentasFrequentes = Object.entries(contagem)
  .sort((a, b) => b[1] - a[1])
  .map(([nome, vezes]) => `${nome} (${vezes}x)`)
  .join(', ');

return [{
  json: {
    tarefas_usadas: tarefasUsadas.join(' | ') || 'nenhuma ainda',
    tarefas_normalizadas: tarefasNormalizadas,
    ferramentas_frequentes: ferramentasFrequentes || 'nenhuma ainda',
    data_hoje: new Date().toLocaleDateString('pt-BR')
  }
}];

try {
  const raw = $input.first().json.output;

  // A IA as vezes envolve o JSON em blocos de codigo markdown (```json ... ```).
  let clean = String(raw).replace(/```json|```/g, '').trim();

  // Com tool de busca conectada, o modelo as vezes escreve uma frase antes do JSON.
  // Recorta do primeiro '{' ate o ultimo '}' para isolar so o objeto.
  const inicio = clean.indexOf('{');
  const fim = clean.lastIndexOf('}');
  if (inicio !== -1 && fim !== -1) {
    clean = clean.slice(inicio, fim + 1);
  }

  const parsed = JSON.parse(clean);

  // ---------- 1) CONTRATO MINIMO ----------
  const faltando = [];
  for (const campo of ['tarefa', 'tema_card', 'dor', 'prompt_exemplo']) {
    if (!parsed[campo]) faltando.push(campo);
  }
  for (const campo of ['slides', 'passo_a_passo', 'cuidados']) {
    if (!Array.isArray(parsed[campo]) || parsed[campo].length === 0) faltando.push(campo);
  }
  if (!parsed.legendas) faltando.push('legendas');
  else {
    for (const rede of ['instagram', 'facebook', 'linkedin']) {
      if (!parsed.legendas[rede]) faltando.push('legendas.' + rede);
    }
  }

  if (faltando.length) {
    return [{ json: { erro: true, mensagem: 'Campos ausentes: ' + faltando.join(', '), bruto: clean } }];
  }

  const avisos = [];

  // ---------- 2) NORMALIZACAO DE PAPEIS ----------
  // A estrutura narrativa e o ponto do post, entao ela e reparada aqui em vez de
  // derrubar o roteiro inteiro. So bloqueia o que nao da para reconstruir.
  let slides = parsed.slides
    .filter(s => s && (s.titulo || s.texto))
    .map(s => ({
      papel: String(s.papel || '').trim().toLowerCase(),
      titulo: String(s.titulo || '').trim(),
      texto: String(s.texto || '').trim()
    }));

  // A IA foi instruida a nao escrever fechamento. Se escrever, o slide sai aqui
  // -- o CTA real e adicionado depois, por codigo, sempre igual.
  const ehFechamento = (s) => /sig(a|ue) (a p[aá]gina|o @|a gente)|nos sig(a|ue)|obrigad[oa] por|at[eé] a pr[oó]xima|salve esse post|compartilhe esse post|link (na|da) bio/i.test(s.titulo + ' ' + s.texto);
  const ultimo = slides[slides.length - 1];
  const cta_indevido = slides.filter(s => s.papel === 'cta' || (s === ultimo && ehFechamento(s)));
  if (cta_indevido.length) {
    slides = slides.filter(s => !cta_indevido.includes(s));
    avisos.push('a IA escreveu ' + cta_indevido.length + ' slide(s) de fechamento; foram removidos');
  }

  // Papel ausente (formato antigo) ou fora de ordem: reconstroi por posicao.
  const semPapel = slides.filter(s => !['gancho', 'contexto', 'desenvolvimento'].includes(s.papel));
  if (semPapel.length) {
    avisos.push('papel ausente ou invalido em ' + semPapel.length + ' slide(s); atribuido por posicao');
  }
  const gancho = slides.find(s => s.papel === 'gancho') || slides[0];
  const contexto = slides.find(s => s.papel === 'contexto' && s !== gancho) ||
                   slides.find(s => s !== gancho);
  const desenvolvimento = slides.filter(s => s !== gancho && s !== contexto);

  if (!gancho || !contexto || desenvolvimento.length === 0) {
    return [{ json: { erro: true, mensagem: 'Estrutura insuficiente: precisa de gancho + contexto + ao menos 1 desenvolvimento. Vieram ' + slides.length + ' slides.', bruto: clean } }];
  }

  const ordemOriginal = slides.map(s => s.papel).join(',');
  gancho.papel = 'gancho';
  contexto.papel = 'contexto';
  desenvolvimento.forEach(s => { s.papel = 'desenvolvimento'; });
  slides = [gancho, contexto, ...desenvolvimento];
  if (ordemOriginal !== slides.map(s => s.papel).join(',') && !semPapel.length) {
    avisos.push('slides estavam fora da ordem gancho > contexto > desenvolvimento; reordenados');
  }

  // ---------- 3) AVISOS DE FORMA (nao bloqueiam) ----------
  if (desenvolvimento.length < 3) avisos.push('so ' + desenvolvimento.length + ' slide(s) de passo a passo (esperado 3 a 7)');
  if (desenvolvimento.length > 7) avisos.push(desenvolvimento.length + ' slides de passo a passo (esperado 3 a 7)');

  const limites = {
    gancho: { min: 0, max: 90 },
    contexto: { min: 80, max: 160 },
    desenvolvimento: { min: 90, max: 180 }
  };
  slides.forEach((s, i) => {
    const lim = limites[s.papel];
    const n = s.texto.length;
    if (n > lim.max) avisos.push('slide ' + (i + 1) + ' (' + s.papel + ') com ' + n + ' chars, limite ' + lim.max);
    if (lim.min && n < lim.min) avisos.push('slide ' + (i + 1) + ' (' + s.papel + ') com ' + n + ' chars, minimo ' + lim.min);
    if (s.titulo.length > 40) avisos.push('titulo do slide ' + (i + 1) + ' com ' + s.titulo.length + ' chars, limite 40');
  });

  parsed.passo_a_passo.forEach((p, i) => {
    const n = String(p || '').length;
    if (n > 180) avisos.push('passo ' + (i + 1) + ' do passo a passo com ' + n + ' chars, limite 180');
  });

  // Gancho que abre como aula em vez de nomear a dor.
  if (/^(voce sabe|você sabe|hoje (vamos|eu vou)|tutorial|aprenda a|como fazer)\b/i.test(gancho.titulo + ' ' + gancho.texto)) {
    avisos.push('o gancho abre como titulo de aula -- reescrever como custo concreto antes de aprovar');
  }

  // ---------- 4) REFERENCIA QUEBRADA ----------
  // O prompt so existe na legenda, e quem avisa isso e o slide de CTA fixo.
  const proibido = /pr[oó]ximo slide|slide seguinte|slide a seguir|logo abaixo|aqui embaixo|nos coment[aá]rios|link da bio/i;
  const apontaLegenda = /na legenda|da legenda/i;

  slides.forEach((s, i) => {
    const texto = `${s.titulo} ${s.texto}`;
    if (proibido.test(texto)) avisos.push(`slide ${i + 1} aponta para lugar inexistente`);
    if (apontaLegenda.test(texto)) avisos.push(`slide ${i + 1} menciona a legenda -- isso agora e papel do slide de fechamento, vai sair repetido`);
  });

  for (const rede of ['instagram', 'facebook', 'linkedin']) {
    if (proibido.test(parsed.legendas[rede])) avisos.push(`legenda ${rede} aponta para lugar inexistente`);
  }

  return [{ json: { ...parsed, slides, erro: false, avisos } }];
} catch (e) {
  return [{ json: { erro: true, mensagem: e.message } }];
}

// Normaliza o nome da tarefa antes de gravar na memoria:
// minusculo, sem acento, sem pontuacao. Evita que "Resumir PDFs" e
// "resumir pdf!" sejam tratados como tarefas diferentes na proxima semana.
function normalizar(texto) {
  return String(texto || "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\w\s]/g, "")
    .replace(/\s+/g, " ");
}

const dados = $input.first().json;

// Garante que os campos de lista existam, para as expressoes seguintes
// nao quebrarem caso o modelo esqueca algum campo.
function lista(valor) {
  return Array.isArray(valor) ? valor : [];
}

const ferramentas = lista(dados.ferramentas);

return [{
  json: {
    ...dados,
    ferramentas,
    passo_a_passo: lista(dados.passo_a_passo),
    cuidados: lista(dados.cuidados),
    slides: lista(dados.slides),
    hashtags: lista(dados.hashtags),
    fontes: lista(dados.fontes),
    prompt_exemplo: String(dados.prompt_exemplo || ''),
    tarefa_normalizada: normalizar(dados.tarefa),
    // guardado como texto simples: a Data Table nao tem coluna do tipo lista
    ferramentas_citadas: ferramentas.join(', '),
    data: new Date().toISOString(),
    status: "gerado"
  }
}];

// CONTRATO COM O FLUXO DE DESIGN
// A descricao do card pai e a fonte unica de verdade. O fluxo de design le esta
// descricao e corta pelos cabecalhos '## ' abaixo -- os mesmos usados nos fluxos
// de segunda e sexta, para um parser so atender os tres. Se voce editar o texto
// no Trello durante a revisao, edite DENTRO das secoes: nao apague nem renomeie
// os cabecalhos, senao o parser do design nao encontra nada.
//
// Cada slide vem marcado com o papel narrativo (GANCHO / CONTEXTO /
// DESENVOLVIMENTO / CTA). O papel escolhe o layout na hora da arte, entao nao
// remova o slide de CTA nem troque a ordem dos papeis na revisao.
//
// SOBRE O PROMPT: ele existe em UM lugar so, a secao '## PROMPT PRONTO'.
// A publicacao anexa esse bloco no fim de cada legenda. Por isso as legendas
// aqui terminam com um marcador -- e lembrete de que o texto publicado vai ser
// maior que o que voce ve, e de que editar o prompt e editar um lugar so.

const d = $input.first().json;

const MARCADOR = '>> Na publicacao, o bloco PROMPT PRONTO entra aqui.';

const slides = d.slides
  .map((s, i) => `### ${i + 1} | ${String(s.papel || '').toUpperCase()} | ${s.titulo}\n${s.texto}`)
  .join('\n\n');

const passos = d.passo_a_passo
  .map((p, i) => `${i + 1}. ${p}`)
  .join('\n');

const cuidados = d.cuidados
  .map(c => `- ${c}`)
  .join('\n');

// Linha comecando com '#' vira titulo no markdown do Trello e a primeira
// hashtag some da tela. A barra invertida escapa; o parser do design remove.
const hashtags = d.hashtags.join(' ').replace(/^#/, '\\#');

const partes = [
  d.dor,
  '',
  '## RESUMO',
  `Tarefa: ${d.tarefa}`,
  `Tempo: ${d.tempo_antes} na mao -> ${d.tempo_depois} com IA`,
  `Ferramentas: ${d.ferramentas.join(', ')}`,
  `Custo: ${d.custo}`,
  '',
  '## PASSO A PASSO',
  passos,
  '',
  '## PROMPT PRONTO',
  d.prompt_exemplo,
  '',
  '## CUIDADOS',
  cuidados,
  '',
  '## SLIDES',
  slides,
  '',
  '## LEGENDA INSTAGRAM',
  d.legendas.instagram,
  MARCADOR,
  '',
  '## LEGENDA FACEBOOK',
  d.legendas.facebook,
  MARCADOR,
  '',
  '## LEGENDA LINKEDIN',
  d.legendas.linkedin,
  MARCADOR,
  '',
  '## HASHTAGS',
  hashtags,
  '',
  '## FONTES',
  d.fontes.join('\n')
];

if (d.avisos && d.avisos.length) {
  partes.push('', '## AVISOS DA AUTOMACAO', d.avisos.map(a => `- ${a}`).join('\n'));
}

return [{
  json: {
    ...d,
    descricao: partes.join('\n')
  }
}];

// Depois do node de checklist, $json e o objeto da checklist -- entao $json.id
// e o checklistId. Um item entra e um item sai: sem risco de pareamento.
const checklistId = $input.first().json.id;

// A validacao pratica vem antes da arte: se o passo a passo nao funcionar na
// vida real, o carrossel inteiro precisa ser refeito.
const tarefas = [
  'Executar o passo a passo na pratica e confirmar que funciona',
  'Testar o prompt de exemplo e ajustar se necessario',
  'Conferir as fontes citadas',
  'Ler so o slide 1: a dor esta concreta o bastante para parar o scroll?',
  'Conferir se o slide 2 promete sem ensinar (ele segura quem parou)',
  'Revisar as tres legendas',
  'Aprovar texto (mover card para Aprovado)',
  'Gerar arte do carrossel',
  'Aprovar arte',
  'Publicar nas tres redes'
];

return [{ json: { checklistId, tarefas } }];
